114	template <typename RetT, typename ReturnT, typename... ArgTs>
115	struct WFHandlerTraitsImpl {
116	  static_assert(std::is_void_v<RetT>,
117	                "Async wrapper function handler must return void");
118	  typedef ReturnT YieldType;
119	  typedef std::tuple<std::decay_t<ArgTs>...> ArgTupleType;
120	
121	  // Forwards arguments based on the parameter types of the handler.
122	  template <typename FnT> class ForwardArgsAsRequested {
123	  public:
124	    ForwardArgsAsRequested(FnT &&Fn) : Fn(std::move(Fn)) {}
125	    void operator()(ArgTs &...Args) { Fn(std::forward<ArgTs>(Args)...); }
126	
127	  private:
128	    FnT Fn;
129	  };
130	
131	  template <typename FnT>
132	  static ForwardArgsAsRequested<std::decay_t<FnT>>
133	  forwardArgsAsRequested(FnT &&Fn) {
134	    return ForwardArgsAsRequested<std::decay_t<FnT>>(std::forward<FnT>(Fn));
135	  }
136	};
