138	template <bool /* is_const */, bool /* is_noexcept */, typename... Ts>
139	struct WFHandlerTraitsImplAdapter : WFHandlerTraitsImpl<Ts...> {};
140	
141	template <typename C>
142	using WFHandlerTraits = CallableTraitsHelper<WFHandlerTraitsImplAdapter, C>;
