144	template <typename Serializer> class StructuredYieldBase {
145	public:
146	  StructuredYieldBase(orc_rt_SessionRef S, orc_rt_WrapperFunctionReturn Return,
147	                      uint64_t CallId, Serializer &&Z)
148	      : S(S), Return(Return), CallId(CallId), Z(std::forward<Serializer>(Z)) {}
149	
150	protected:
151	  orc_rt_SessionRef S;
152	  orc_rt_WrapperFunctionReturn Return;
153	  uint64_t CallId;
154	  std::decay_t<Serializer> Z;
155	};
