157	template <typename RetT, typename Serializer> class StructuredYield;
158	
159	template <typename RetT, typename Serializer>
160	class StructuredYield<std::tuple<RetT>, Serializer>
161	    : public StructuredYieldBase<Serializer> {
162	public:
163	  using StructuredYieldBase<Serializer>::StructuredYieldBase;
164	  void operator()(RetT &&R) {
165	    if (auto ResultBytes = this->Z.result().serialize(std::forward<RetT>(R)))
166	      this->Return(this->S, ResultBytes->release(), this->CallId);
167	    else
168	      this->Return(this->S,
169	                   WrapperFunctionBuffer::createOutOfBandError(
170	                       "Could not serialize wrapper function result data")
171	                       .release(),
172	                   this->CallId);
173	  }
174	};
175	
176	template <typename Serializer>
177	class StructuredYield<std::tuple<>, Serializer>
178	    : public StructuredYieldBase<Serializer> {
179	public:
180	  using StructuredYieldBase<Serializer>::StructuredYieldBase;
181	  void operator()() {
182	    this->Return(this->S, WrapperFunctionBuffer().release(), this->CallId);
183	  }
184	};
