201	template <typename Serializer>
202	struct ResultDeserializer<std::tuple<Error>, Serializer> {
203	  static Error deserialize(WrapperFunctionBuffer ResultBytes, Serializer &S) {
204	    assert(ResultBytes.empty());
205	    return Error::success();
206	  }
