211	/// Provides call and handle utilities to simplify writing and invocation of
212	/// wrapper functions in C++.
213	struct WrapperFunction {
214	
215	  /// Wraps an asynchronous method (a method returning void, and taking a
216	  /// return callback as its first argument) for use with
217	  /// WrapperFunction::handle.
218	  ///
219	  /// AsyncMethod's call operator takes an ExecutorAddr as its second argument,
220	  /// casts it to a ClassT*, and then calls the wrapped method on that pointer,
221	  /// forwarding the return callback and any subsequent arguments (after the
222	  /// second argument representing the object address).
223	  ///
224	  /// This utility removes some of the boilerplate from writing wrappers for
225	  /// method calls.
226	  template <typename ClassT, typename ReturnT, typename... ArgTs>
227	  struct AsyncMethod {
228	    AsyncMethod(void (ClassT::*M)(ReturnT, ArgTs...)) : M(M) {}
229	    void operator()(ReturnT &&Return, ExecutorAddr Obj, ArgTs &&...Args) {
230	      (Obj.toPtr<ClassT *>()->*M)(std::forward<ReturnT>(Return),
231	                                  std::forward<ArgTs>(Args)...);
232	    }
233	
234	  private:
235	    void (ClassT::*M)(ReturnT, ArgTs...);
236	  };
