387	      std::apply(HandlerTraits::forwardArgsAsRequested(bind_front(
388	                     std::forward<Handler>(H),
389	                     detail::StructuredYield<RetTupleType, Serializer>(
390	                         S, Return, CallId, std::move(Z)))),
